     3	const sanitizeHtml = require('sanitize-html');
     4	
     5	const MAX_DEPTH = 100;
     6	
     7	function hasOwn(object, key) {
     8	  const keys = Reflect.ownKeys(object).filter((item) => typeof item !== 'symbol');
     9	  return keys.includes(key);
    10	}
    11	
    12	const initializeOptions = (options) => {
    13	  const sanitizerOptions = {};
    14	  if (hasOwn(options, 'allowedTags') && Array.isArray(options.allowedTags) && options.allowedTags.length > 0) {
    15	    sanitizerOptions.allowedTags = options.allowedTags;
    16	  }
    17	
    18	  if (hasOwn(options, 'allowedAttributes') && Object.keys(options.allowedAttributes).length > 0) {
    19	    sanitizerOptions.allowedAttributes = options.allowedAttributes;
    20	  }
    21	
    22	  return {
    23	    allowedKeys: (hasOwn(options, 'allowedKeys') && Array.isArray(options.allowedKeys) && options.allowedKeys) || [],
    24	    maxDepth:
    25	      hasOwn(options, 'maxDepth') && typeof options.maxDepth === 'number' && options.maxDepth > 0
    26	        ? options.maxDepth
    27	        : MAX_DEPTH,
    28	    sanitizerOptions,
    29	  };
    30	};
    31	
    32	const sanitize = (options, data, currentDepth = 0) => {
    33	  if (currentDepth > options.maxDepth) {
    34	    throw new Error(`Maximum sanitization depth of ${options.maxDepth} exceeded`);
    35	  }
    36	  if (typeof data === 'string') {
    37	    return sanitizeHtml(data, options.sanitizerOptions);
    38	  }
    39	  if (Array.isArray(data)) {
    40	    return data.map((item) => {
    41	      if (typeof item === 'string') {
    42	        return sanitizeHtml(item, options.sanitizerOptions);
    43	      }
    44	      if (Array.isArray(item) || typeof item === 'object') {
    45	        return sanitize(options, item, currentDepth + 1);
    46	      }
    47	      return item;
    48	    });
    49	  }
    50	  if (typeof data === 'object' && data !== null) {
    51	    Object.keys(data).forEach((key) => {
    52	      if (options.allowedKeys.includes(key)) {
    53	        return;
    54	      }
    55	      const item = data[key];
    56	      if (typeof item === 'string') {
    57	        data[key] = sanitizeHtml(item, options.sanitizerOptions);
    58	      } else if (Array.isArray(item) || typeof item === 'object') {
    59	        data[key] = sanitize(options, item, currentDepth + 1);
    60	      }
    61	    });
    62	  }
    63	  return data;
    64	};
    65	
    66	const prepareSanitize = (data, options = {}) => {
    67	  options = initializeOptions(options);
    68	  return sanitize(options, data);
    69	};
    70	
    71	module.exports = prepareSanitize;

